import React, { useState, useEffect } from "react";
import emailjs from "@emailjs/browser";
import "./brutalist-button.css";

export default function ValentineApp() {
    const [page, setPage] = useState("home");
    const [userName, setUserName] = useState("");
    const [selectedColor, setSelectedColor] = useState("");

    useEffect(() => {
        emailjs.init(
            process.env.REACT_APP_EMAILJS_PUBLIC_KEY || "YOUR_PUBLIC_KEY"
        );
    }, []);

    return (
        <div className="valentine-container">

            {/* Floating Hearts */}
            <div className="wrapper">
                <div className="heart x1"></div>
                <div className="heart x2"></div>
                <div className="heart x3"></div>
                <div className="heart x4"></div>
                <div className="heart x5"></div>
                <div className="altheart x6"></div>
            </div>

            {/* Routing */}
            {page === "home" && <HomePage onYes={() => setPage("game")} />}
            {page === "game" && <DinoGamePage onFinish={() => setPage("input")} />}

            {page === "input" && (
                <InputPage
                    userName={userName}
                    setUserName={setUserName}
                    selectedColor={selectedColor}
                    setSelectedColor={setSelectedColor}
                    onSubmit={() => setPage("final")}
                />
            )}

            {page === "final" && (
                <FinalPage
                    userName={userName}
                    selectedColor={selectedColor}
                />
            )}

            {/* Styles */}
            <style>{`
        @import url('https://fonts.googleapis.com/css2?family=Pacifico&family=Quicksand:wght@400;600;700&display=swap');

        * {
          margin: 0;
          padding: 0;
          box-sizing: border-box;
        }

        body {
          font-family: 'Quicksand', sans-serif;
        }

        .valentine-container {
          min-height: 100vh;
          background: linear-gradient(135deg,#FFE5EC,#FFCDB2,#E4C1F9);
          position: relative;
          overflow: hidden;
        }

        /* Floating Hearts */

        .wrapper {
          position: fixed;
          inset: 0;
          overflow: hidden;
          pointer-events: none;
          z-index: 1;
        }

        .heart,
        .altheart {
          position: absolute;
          bottom: -100px;
        }

        .x1 {
          left: 5%;
          transform: scale(0.9);
          opacity: 0.6;
          animation: move 15s linear infinite, side 4s ease-in-out infinite alternate;
        }

        .x2 {
          left: 25%;
          transform: scale(0.6);
          opacity: 0.9;
          animation: move 25s linear infinite, side 5s ease-in-out infinite alternate;
        }

        .x3 {
          left: 55%;
          transform: scale(0.8);
          opacity: 0.8;
          animation: move 20s linear infinite, side 4s ease-in-out infinite alternate;
        }

        .x4 {
          left: 72%;
          transform: scale(0.75);
          opacity: 0.9;
          animation: move 18s linear infinite, side 2s ease-in-out infinite alternate;
        }

        .x5 {
          left: 88%;
          transform: scale(0.8);
          opacity: 0.3;
          animation: move 12s linear infinite, side 2s ease-in-out infinite alternate;
        }

        .x6 {
          left: 33%;
          animation: move 10s linear infinite, sway 6s ease-in-out infinite alternate;
        }

        @keyframes move {
          from { top: 100%; }
          to { top: -200px; }
        }

        @keyframes side {
          from { margin-left: 0; }
          to { margin-left: 50px; }
        }

        @keyframes sway {
          0% { transform: rotate(12deg); }
          50% { transform: rotate(-5deg); }
          100% { transform: rotate(0deg); }
        }

        .heart:before,
        .heart:after {
          content: "";
          position: absolute;
          width: 18px;
          height: 30px;
          background: #ff4d6d;
          border-radius: 30px 30px 0 0;
        }

        .heart:before {
          left: 18px;
          transform: rotate(-45deg);
          transform-origin: 0 100%;
        }

        .heart:after {
          left: 0;
          transform: rotate(45deg);
          transform-origin: 100% 100%;
        }

        .altheart {
          background: url("https://static.indigoimages.ca/2016/shop/113439_img25_twotoneheart.png") no-repeat center/contain;
          width: 24px;
          height: 21px;
        }

        /* Home Page */

        .home-page {
          min-height: 100vh;
          display: flex;
          flex-direction: column;
          justify-content: center;
          align-items: center;
          gap: 40px;
          z-index: 2;
          position: relative;
          text-align: center;
        }

        .title {
          font-family: 'Pacifico', cursive;
          font-size: clamp(2.5rem,6vw,4rem);
          color: #ff6b9d;
        }

        /* Game */

        .game-page {
          min-height: 100vh;
          display: flex;
          flex-direction: column;
          justify-content: center;
          align-items: center;
          gap: 20px;
          z-index: 2;
        }

        .game-box {
          width: 320px;
          height: 150px;
          border: 3px solid #ff6b9d;
          border-radius: 15px;
          background: #fff;
          position: relative;
          overflow: hidden;
        }

        .dino {
          position: absolute;
          left: 20px;
          bottom: 0;
          font-size: 2rem;
          transition: bottom .15s;
        }

        .cactus {
          position: absolute;
          bottom: 0;
          font-size: 1.8rem;
        }

        .game-over {
          text-align: center;
        }

        /* Input */

        .input-page {
          min-height: 100vh;
          display: flex;
          justify-content: center;
          align-items: center;
          z-index: 2;
        }

        .input-card {
          background: #fff;
          padding: 40px;
          border-radius: 25px;
          width: 100%;
          max-width: 450px;
          box-shadow: 0 20px 40px rgba(255,107,157,.3);
        }

        .input-title {
          font-family: 'Pacifico';
          text-align: center;
          margin-bottom: 30px;
          color: #ff6b9d;
        }

        .text-input {
          width: 100%;
          padding: 14px;
          border-radius: 12px;
          border: 2px solid #ffb3c6;
          margin-top: 8px;
        }

        .submit-button {
          width: 100%;
          margin-top: 25px;
          padding: 14px;
          background: #ff6b9d;
          border: none;
          color: #fff;
          border-radius: 40px;
          font-weight: 700;
          cursor: pointer;
        }

        /* Final */

        .final-page {
          min-height: 100vh;
          display: flex;
          flex-direction: column;
          justify-content: center;
          align-items: center;
          text-align: center;
          z-index: 2;
        }

        .final-message {
          font-family: 'Pacifico';
          color: #ff6b9d;
          font-size: 2.5rem;
        }
      `}</style>

        </div>
    );
}

/* HOME */

function HomePage({ onYes }) {

    const [pos, setPos] = useState({ x: 0, y: 0 });
    const [moved, setMoved] = useState(false);

    const move = () => {
        const x = Math.random() * (window.innerWidth - 200);
        const y = Math.random() * (window.innerHeight - 100);

        setPos({ x, y });
        setMoved(true);
    };

    return (
        <div className="home-page">

            <h1 className="title">Will you be my Valentine? 💝</h1>

            {/* YES */}
            <button
                className="brutalist-button button-1 yes-brutal"
                onClick={onYes}
            >
                YES 💖
            </button>

            {/* NO */}
            <button
                className="brutalist-button button-1 no-brutal"
                onMouseEnter={move}
                onClick={move}
                onTouchStart={move}
                style={
                    moved
                        ? { left: pos.x, top: pos.y, position: "absolute" }
                        : { position: "relative" }
                }
            >
                NO 😜
            </button>

        </div>
    );
}

