/* INPUT */

function InputPage({
                       userName,
                       setUserName,
                       selectedColor,
                       setSelectedColor,
                       onSubmit,
                   }) {

    const colors = ["Pink", "Peach", "Lavender", "Mint", "Coral", "Blue"];

    return (
        <div className="input-page">

            <div className="input-card">

                <h2 className="input-title">Tell me about you 💕</h2>

                <label>Name</label>
                <input
                    className="text-input"
                    value={userName}
                    onChange={(e) => setUserName(e.target.value)}
                />

                <label style={{ marginTop: "15px" }}>Color</label>

                <select
                    className="text-input"
                    value={selectedColor}
                    onChange={(e) => setSelectedColor(e.target.value)}
                >
                    <option value="">Choose</option>

                    {colors.map(c => (
                        <option key={c}>{c}</option>
                    ))}

                </select>

                <button
                    className="submit-button"
                    disabled={!userName || !selectedColor}
                    onClick={onSubmit}
                >
                    Submit 💌
                </button>

            </div>

        </div>
    );
}

